module accu (
	input clk, rst_n, valid_in,
	input [7:0] data_in,
	output reg valid_out,
	output reg [9:0] data_out
);
	reg [1:0] cnt;
	reg [9:0] sum;

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			cnt <= 2'd0;
			sum <= 10'd0;
			valid_out <= 1'd0;
		end
		else begin
			if(valid_in) begin
				cnt <= cnt + 2'd1;
				sum <= sum + data_in;
				if(cnt == 2'd3) begin
					valid_out <= 1'd1;
					cnt <= 2'd0;
					sum <= 10'd0;
				end
				else begin
					valid_out <= 1'd0;
				end
			end
		end
	end

	always@(*) begin
		if(cnt == 2'd3) begin
			data_out <= sum;
		end
	end
endmodule
